    W_out = W // 3

    result = []
    for r in range(H_out):
        row_res = []
        for c in range(W_out):
            # Identify all pixels in the 3x3 block
            counts = {}
            base_r, base_c = r * 3, c * 3
            for dr in range(3):
                for dc in range(3):
                    val = grid[base_r + dr][base_c + dc]
                    counts[val] = counts.get(val, 0) + 1

            # Select the most frequent color (tie-breaker: smallest value for determinism)
            if counts:
                best_color = min(counts, key=lambda k: (-counts[k], k))
                row_res.append(best_color)
            else:
                row_res.append(0)
        result.append(row_res)

